import { z } from "zod"

// data/models.ts — a curated, DATED snapshot of frontier + notable LLMs for the
// /models comparison page. A snapshot, not a live feed: leaderboards churn.
//
// Method (snapshot 2026-11-12): every AA-measured value was read on one day
// from the per-model records in Artificial Analysis's Next.js payload. Since
// October the leaderboard page (artificialanalysis.ai/leaderboards/models)
// embeds only AA's 284 current, non-deprecated variants, so the records were
// taken from a per-model page (artificialanalysis.ai/models/o3), which embeds
// all 735 variants, deprecated ones included. Every record on the leaderboard
// page is identical to its copy there, and a second per-model page (kimi-k3)
// matches the first exactly. Field mapping (AA renamed the speed fields):
//   intelligence = intelligenceIndex, AA Intelligence Index v5.0.1. AA moved
//                  from v4.3.2 to v5.0 in October (HLE-Diamond,
//                  Terminal-Bench-Science and FrontierCode-AA 2.0 added;
//                  GDPval-AA, SciCode, AA-LCR and HLE dropped; CritPt replaced
//                  by CritPt v2 Hard; four equal categories) and to v5.0.1 in
//                  November (CritPt v2 regraded). The scale is new: GLM-5.3 was
//                  44.8 on v4.3.2 and is 31.7 on v5.0.1. AA has scored only 122
//                  variants on v5, so a model it has not re-run is null here.
//                  No v4 score is carried over, and a lower-effort variant's
//                  score is never substituted for the one this rule picks.
//   priceIn/Out  = price1mInputTokens / price1mOutputTokens (USD per 1M tokens)
//   speedTps     = headline.outputSpeed (was medianOutputTokensPerSecond)
//   latencyS     = headline.timeToFirstToken (was medianTimeToFirstTokenSeconds;
//                  first token of any kind, so reasoning tokens count. AA also
//                  reports timeToFirstAnswerToken, which is not used)
//   contextK     = contextWindowTokens / 1000, rounded
// A model is shown as AA's highest-effort reasoning variant (max, else xhigh,
// high, plain "Reasoning", medium); `note` names the variant and says when AA
// has no v5 score for it or marks it deprecated. AA's payload no longer flags
// estimated scores, so notes no longer say "estimated". A field AA has no value
// for is null, except list prices already sourced in July, which are kept and
// say so. `released` is AA's release date where the record had none, and
// `sizeB` is AA's `parameters` where the row had no size. Models AA does not
// list come from llm-stats (api.zeroeval.com), provider docs, Hugging Face and
// this site's articles, and carry no AA-measured fields. Per-model sources are
// in data/models-sources.md. `eci` is Epoch's Capabilities Index, read from
// eci_scores.csv in epoch.ai/data/benchmark_data.zip on the same day, where
// Epoch scores the same model version. Any value that isn't sourced is `null`,
// never guessed — the UI renders around missing data.
// Blended price follows AA's 3:1 input:output convention.

export const MODELS_SNAPSHOT_DATE = "2026-11-12"
export const MODELS_INDEX_VERSION = "v5.0.1"

export type Origin = "US" | "China" | "EU" | "Canada" | "UAE" | "Korea" | "Israel" | "India" | "Other"

export type ModelRecord = {
  name: string
  provider: string
  origin: Origin
  openWeights: boolean
  sizeB: number | null
  intelligence: number | null
  eci: number | null
  priceIn: number | null
  priceOut: number | null
  speedTps: number | null
  latencyS: number | null
  contextK: number | null
  released: string | null
  article?: string
  note?: string
}

export function blendedPrice(m: ModelRecord): number | null {
  if (m.priceIn == null || m.priceOut == null) return null
  return Math.round(((m.priceIn * 3 + m.priceOut) / 4) * 1000) / 1000
}

// Context window label: AA reports exact token counts, so 1,048,576 tokens is
// contextK 1049; show it as "1.05M", not "1.049M".
export function contextLabel(k: number): string {
  return k >= 1000 ? `${Math.round(k / 10) / 100}M` : `${k}K`
}

